insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-145', 'sus', null, 'Uma gestante negra, moradora de área rural, com hipertensão arterial crônica, inicia o pré-natal na UBS e relata dificuldade de transporte e medo de não conseguir vaga na maternidade. Com base nos objetivos da Rede Alyne, a conduta correta da equipe é:', '["garantir a vinculação da gestante à maternidade de referência e acionar o sistema logístico para assegurar o transporte, mantendo o acompanhamento na Atenção Básica.","informar que a Rede Alyne é focada apenas no parto e que o transporte deve ser providenciado pela gestante.","encaminhar a gestante ao pré-natal de alto risco e encerrar o acompanhamento na Atenção Básica.","recomendar apenas teleconsultas, dispensando consultas presenciais.","realizar o pré-natal de alto risco exclusivamente na UBS, sem articulação com a maternidade."]'::jsonb, 0, 'A rede prevê vinculação à maternidade, transporte sanitário e regulação, e a gestante de alto risco continua acompanhada pela Atenção Básica (cuidado compartilhado).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-146', 'sus', null, 'Considerando a organização do componente pré-natal da Rede Alyne, assinale a alternativa que apresenta pontos de atenção que o constituem.', '["Unidade Básica de Saúde, ambulatório especializado e Ambulatório de Gestação e Puerpério de Alto Risco (AGPAR).","Estratégia Saúde da Família, Centro de Atenção Psicossocial e SAMU 192.","UPA 24h, maternidade de referência e UTI neonatal.","UBS, equipe de Consultório na Rua e Centro de Referência de Assistência Social.","Centro de Parto Normal, banco de leite humano e CAPS."]'::jsonb, 0, 'O pré-natal se organiza na APS, com referência a ambulatórios especializados e ao AGPAR para a gestação de alto risco.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-147', 'sus', null, 'Sobre a Rede Alyne (Portaria GM/MS nº 5.350/2024), registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-148', 'sus', null, 'A Rede Alyne deve ser integrada ao ______ para organização de forma ______, considerando as especificidades, o perfil epidemiológico e a capacidade instalada nos diferentes territórios. Assinale a alternativa que preenche corretamente as lacunas.', '["Planejamento Regional Integrado (PRI) — ascendente","Plano Nacional de Saúde (PNS) — hierarquizada","Plano Diretor de Regionalização (PDR) — centralizada","Programa Anual de Saúde (PAS) — integrada","Planejamento Estratégico Municipal (PEM) — descendente"]'::jsonb, 0, 'As redes de atenção são organizadas no âmbito do Planejamento Regional Integrado, de forma ascendente, a partir das necessidades locais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-149', 'sus', null, 'A Rede de Atenção Psicossocial (RAPS), instituída pela Portaria nº 3.088/2011, é composta por diferentes componentes. Registre V para os componentes da RAPS e F para o que não é componente.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-150', 'sus', null, 'Considerando as diretrizes da RAPS, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-151', 'sus', null, 'Na RAPS, o componente Atenção Residencial de Caráter Transitório é constituído por:', '["Unidades de Acolhimento e Serviços de Atenção em Regime Residencial.","Serviços Residenciais Terapêuticos.","CAPS III e CAPS AD III.","enfermarias especializadas em hospital geral.","Centros de Convivência e Cultura."]'::jsonb, 0, 'Os Serviços Residenciais Terapêuticos pertencem às Estratégias de Desinstitucionalização.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-152', 'sus', null, 'Na RAPS, as ações de geração de trabalho e renda, os empreendimentos solidários e as cooperativas sociais compõem o componente:', '["Reabilitação Psicossocial.","Atenção Básica em Saúde.","Atenção Hospitalar.","Atenção de Urgência e Emergência.","Atenção Residencial de Caráter Transitório."]'::jsonb, 0, 'A reabilitação psicossocial busca a inclusão produtiva e o exercício da cidadania.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-153', 'sus', null, 'Em uma UBS, a equipe de Saúde da Família recebe um usuário em sofrimento psíquico e discute a melhor forma de organizar o seu cuidado no território, recorrendo ao apoio matricial. Sobre essa estratégia, é correto afirmar que:', '["o apoio matricial oferece suporte especializado às equipes da Atenção Básica no cuidado em saúde mental, com corresponsabilização.","o matriciamento substitui a Atenção Básica pela internação em hospital psiquiátrico.","o acolhimento em saúde mental consiste no encaminhamento imediato ao serviço especializado.","o apoio matricial transfere definitivamente o usuário para o CAPS.","o matriciamento é realizado apenas por médicos psiquiatras."]'::jsonb, 0, 'O matriciamento envolve discussão de casos, atendimentos conjuntos e educação permanente, mantendo o vínculo do usuário com a equipe de referência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-154', 'sus', null, 'A Rede de Cuidados à Pessoa com Deficiência, instituída pela Portaria GM/MS nº 793/2012, organiza-se nos componentes:', '["Atenção Básica; Atenção Especializada em Reabilitação Auditiva, Física, Intelectual, Visual, Ostomia e em Múltiplas Deficiências; e Atenção Hospitalar e de Urgência e Emergência.","Atenção Básica e Atenção Psicossocial Especializada, exclusivamente.","Atenção hospitalar de longa permanência e instituições de abrigamento.","Escolas especiais e centros de assistência social.","Pré-natal, parto e puerpério."]'::jsonb, 0, 'O ponto especializado de referência é o Centro Especializado em Reabilitação (CER), além das oficinas ortopédicas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-155', 'sus', null, 'A atenção à pessoa com deficiência busca a inclusão e a autonomia, com ações organizadas na rede de atenção. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-156', 'sus', null, 'No âmbito da Rede de Cuidados à Pessoa com Deficiência, o Centro Especializado em Reabilitação (CER) é classificado conforme:', '["o número de modalidades de reabilitação que oferta (CER II, III ou IV).","o número de leitos de internação.","a quantidade de médicos especialistas.","a renda média da população atendida.","o porte do hospital ao qual está vinculado."]'::jsonb, 0, 'CER II: duas modalidades; CER III: três; CER IV: quatro (auditiva, física, intelectual e visual).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-157', 'sus', null, 'A Política Nacional de Saúde da Pessoa Idosa (Portaria nº 2.528/2006) orienta o cuidado à população idosa no SUS. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-158', 'sus', null, 'A Caderneta de Saúde da Pessoa Idosa é um instrumento de acompanhamento que reúne informações de saúde e apoia o cuidado longitudinal do idoso na Atenção Básica. Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-159', 'sus', null, 'Na rotina de uma UBS, a equipe identifica baixa procura de homens adultos pelos serviços e discute as diretrizes da Política Nacional de Atenção Integral à Saúde do Homem (PNAISH). Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-160', 'sus', null, 'A Política Nacional de Atenção Integral à Saúde da Mulher (PNAISM) tem como princípios norteadores, entre outros:', '["a integralidade e a perspectiva de gênero, com humanização e qualidade da atenção.","o foco exclusivo na saúde reprodutiva da mulher.","o atendimento restrito às mulheres em idade fértil.","a centralização das ações nos hospitais-maternidade.","a exclusão das mulheres no climatério."]'::jsonb, 0, 'A PNAISM amplia o cuidado para além do ciclo gravídico-puerperal, incluindo climatério, violência, saúde mental e doenças crônicas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-161', 'sus', null, 'Em um município, a equipe identifica aumento de agravos relacionados ao trabalho e planeja ações com base na Política Nacional de Saúde do Trabalhador e da Trabalhadora (Portaria nº 1.823/2012). Registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-162', 'sus', null, 'No âmbito da saúde do trabalhador, a Rede Nacional de Atenção Integral à Saúde do Trabalhador (RENAST) tem como pontos de referência técnica regionais os:', '["Centros de Referência em Saúde do Trabalhador (CEREST).","Centros de Atenção Psicossocial (CAPS).","Centros Especializados em Reabilitação (CER).","Centros de Referência de Assistência Social (CRAS).","Centros de Testagem e Aconselhamento (CTA)."]'::jsonb, 0, 'Os CEREST oferecem suporte técnico e são polos irradiadores das ações de saúde do trabalhador.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-163', 'sus', null, 'No campo da saúde do trabalhador, a identificação de acidentes e doenças relacionados ao trabalho envolve instrumentos de comunicação e notificação. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-164', 'sus', null, 'A Política Nacional de Promoção da Saúde (PNPS), revisada em 2014, elenca temas prioritários. É um desses temas:', '["promoção da mobilidade segura.","ampliação da oferta de leitos de UTI.","privatização dos serviços de atenção básica.","aumento das internações hospitalares.","centralização da gestão no Ministério da Saúde."]'::jsonb, 0, 'Temas prioritários: formação e educação permanente; alimentação adequada e saudável; práticas corporais e atividades físicas; enfrentamento do tabaco; enfrentamento do uso abusivo de álcool e outras drogas; mobilidade segura; cultura da paz e direitos humanos; desenvolvimento sustentável.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-165', 'sus', null, 'A Política Nacional de Saúde Integral da População Negra (Portaria nº 992/2009) tem como marca:', '["o reconhecimento do racismo, das desigualdades étnico-raciais e do racismo institucional como determinantes sociais das condições de saúde.","a criação de serviços de saúde exclusivos para a população negra.","a dispensa do registro do quesito raça/cor nos sistemas de informação.","a restrição do acesso de outros grupos aos serviços de Atenção Básica.","a substituição dos princípios do SUS por critérios étnicos."]'::jsonb, 0, 'A política reforça a equidade; a coleta do quesito raça/cor, por autodeclaração, é obrigatória nos sistemas de informação do SUS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-166', 'sus', null, 'O Programa Nacional de Segurança do Paciente (Portaria nº 529/2013) adota definições para orientar suas ações. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-167', 'sus', null, 'A Política Nacional de Educação Permanente em Saúde define a educação permanente como:', '["aprendizagem no trabalho, em que o aprender e o ensinar se incorporam ao cotidiano das organizações, com base na problematização do processo de trabalho.","cursos de atualização realizados exclusivamente fora do horário de trabalho.","transmissão vertical de conteúdos técnicos pelos especialistas.","capacitação obrigatória apenas para profissionais recém-contratados.","treinamentos pontuais sem relação com as necessidades do serviço."]'::jsonb, 0, 'A educação permanente parte dos problemas reais do serviço, envolvendo trabalhadores, gestão, ensino e controle social.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-168', 'sus', null, 'A Política Nacional de Vigilância em Saúde (Resolução CNS nº 588/2018) compreende a articulação dos saberes, processos e práticas relacionados à:', '["vigilância epidemiológica, vigilância em saúde ambiental, vigilância em saúde do trabalhador e vigilância sanitária.","assistência hospitalar e ambulatorial de média complexidade.","fiscalização tributária dos estabelecimentos de saúde.","regulação de planos privados de saúde.","formação de profissionais de nível superior."]'::jsonb, 0, 'A PNVS integra as vigilâncias, alinhando-as ao conjunto de políticas do SUS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-169', 'sus', null, 'No território de uma equipe, o enfermeiro observa a presença de vetores e reservatórios de doenças e busca articular ações com o centro de controle de zoonoses do município. Sobre essas atribuições, é correto afirmar que:', '["o centro de controle de zoonoses atua no controle das doenças transmitidas por animais à população.","a vigilância ambiental restringe sua atuação à inspeção de estabelecimentos comerciais.","as ações do controle de zoonoses limitam-se às doenças transmitidas entre seres humanos.","a vigilância da qualidade da água para consumo humano compete exclusivamente à vigilância epidemiológica.","o controle de vetores só é iniciado após a confirmação laboratorial dos casos."]'::jsonb, 0, 'As ações de controle de vetores e reservatórios são preventivas e articuladas com a vigilância ambiental.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-170', 'sus', null, 'A vigilância sanitária integra o SUS e atua sobre fatores capazes de causar dano à saúde da população. Analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-171', 'sus', null, 'As Redes de Atenção à Saúde (RAS) são organizações poliárquicas de conjuntos de serviços de saúde. Nesse modelo, o centro de comunicação da rede, responsável por coordenar o cuidado, é:', '["a Atenção Primária à Saúde.","o hospital de alta complexidade.","a Central de Regulação de Leitos.","o pronto-socorro.","o ambulatório de especialidades."]'::jsonb, 0, 'Na concepção de RAS, a APS é o centro de comunicação, coordenadora do cuidado e ordenadora da rede.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-172', 'sus', null, 'Sobre as Redes de Atenção à Saúde (RAS), registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-173', 'sus', null, 'Uma Unidade de Pronto Atendimento recebe um paciente com dor torácica. Após a estabilização, a equipe aciona a Central de Regulação para transferência a um hospital com hemodinâmica. Nessa situação, a articulação entre os pontos da rede é responsabilidade principal:', '["da regulação médica das urgências, elemento ordenador e orientador da RUE.","da família do paciente, que deve providenciar o transporte.","do Conselho Municipal de Saúde.","da Vigilância Sanitária.","do hospital privado mais próximo, sem necessidade de regulação."]'::jsonb, 0, 'A regulação médica organiza o fluxo e garante o acesso ao recurso adequado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-174', 'sus', null, 'Um município de pequeno porte deseja implantar um serviço para o atendimento de pessoas com sofrimento psíquico grave e persistente. Considerando a RAPS, o serviço de base territorial e comunitária, substitutivo ao modelo asilar, indicado para esse cuidado é o:', '["Centro de Atenção Psicossocial (CAPS).","hospital psiquiátrico.","Serviço Residencial Terapêutico.","Centro de Referência em Saúde do Trabalhador.","ambulatório de neurologia."]'::jsonb, 0, 'O CAPS é o ponto estratégico de atenção psicossocial especializada da RAPS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-175', 'sus', null, 'Uma pessoa com deficiência física recente, após alta hospitalar, precisa de reabilitação e de órtese. O ponto de atenção especializado de referência para esse cuidado, na Rede de Cuidados à Pessoa com Deficiência, é o:', '["Centro Especializado em Reabilitação (CER), com acesso a oficina ortopédica.","CAPS AD.","Centro de Referência de Assistência Social.","UPA 24h.","Serviço Residencial Terapêutico."]'::jsonb, 0, 'O CER oferta reabilitação, e as oficinas ortopédicas confeccionam e adaptam órteses, próteses e meios auxiliares de locomoção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-176', 'sus', null, 'Uma trabalhadora informal, vendedora ambulante, sofre um acidente durante o trabalho e é atendida na UPA. Segundo a Política Nacional de Saúde do Trabalhador e da Trabalhadora, é correto afirmar que:', '["ela é sujeito da política, que alcança todos os trabalhadores, independentemente de vínculo formal, e o acidente deve ser notificado.","ela não é contemplada pela política, por não ter carteira assinada.","o atendimento deve ser cobrado, por se tratar de acidente de trabalho.","o caso deve ser encaminhado exclusivamente à previdência social.","a notificação só é obrigatória para trabalhadores do setor público."]'::jsonb, 0, 'A PNSTT abrange trabalhadores formais e informais, autônomos, desempregados e aposentados.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-177', 'sus', null, 'Na RUE, o componente que tem como objetivo garantir a continuidade do cuidado no domicílio, contribuindo para a desospitalização e a redução de internações, é a:', '["Atenção Domiciliar.","Força Nacional do SUS.","Sala de Estabilização.","Central de Regulação.","UPA 24h."]'::jsonb, 0, 'A Atenção Domiciliar integra a RUE e articula o cuidado pós-urgência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-178', 'sus', null, 'As Unidades de Pronto Atendimento (UPA 24h), na RUE, caracterizam-se como:', '["estabelecimentos de saúde de complexidade intermediária entre as UBS e a rede hospitalar, que funcionam 24 horas por dia.","unidades de internação de longa permanência.","serviços que substituem a Atenção Básica no acompanhamento de doenças crônicas.","centros de reabilitação física.","unidades exclusivas de atendimento a gestantes."]'::jsonb, 0, 'As UPA compõem a rede organizada de atenção às urgências, articuladas à Atenção Básica, ao SAMU e aos hospitais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-179', 'sus', null, 'Sobre o atendimento pré-hospitalar e a regulação das urgências, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-180', 'sus', null, 'Em relação à integração entre as redes de atenção, uma gestante em sofrimento psíquico grave, usuária de crack, em situação de rua, deve ser acompanhada:', '["de forma articulada entre a equipe de Consultório na Rua, a Rede Alyne e a RAPS, com garantia do pré-natal e do cuidado psicossocial.","exclusivamente pelo CAPS AD, sem pré-natal.","exclusivamente pela maternidade, após o parto.","apenas pela assistência social, sem envolvimento da saúde.","por meio de internação compulsória imediata, como primeira medida."]'::jsonb, 0, 'Situações de maior vulnerabilidade exigem cuidado intersetorial e articulação entre as redes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-181', 'sus', null, 'Na RAPS, o serviço que atende pessoas com sofrimento ou transtornos mentais graves e persistentes e com necessidades decorrentes do uso de crack, álcool e outras drogas, com funcionamento 24 horas, inclusive feriados e fins de semana, e com até 12 leitos de acolhimento noturno, é o:', '["CAPS AD III.","CAPS I.","CAPS i.","Serviço Residencial Terapêutico.","Centro de Convivência."]'::jsonb, 0, 'O CAPS AD III oferece atenção contínua 24 horas e acolhimento noturno.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-182', 'sus', null, 'Considerando as políticas de equidade no SUS, analise as afirmativas a seguir.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-183', 'sus', null, 'No contexto da Política Nacional de Humanização, a "equipe de referência" associada ao "apoio matricial" busca:', '["fortalecer o vínculo e a responsabilização de uma equipe por um conjunto de usuários, com suporte especializado compartilhado.","dividir o cuidado em procedimentos isolados, sem responsável definido.","transferir a responsabilidade pelo usuário para o especialista.","reduzir o contato entre profissionais e usuários.","eliminar a participação dos usuários nas decisões terapêuticas."]'::jsonb, 0, 'A equipe de referência é responsável longitudinalmente pelo usuário; o apoio matricial amplia sua capacidade de resposta.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-184', 'sus', null, 'O Projeto Terapêutico Singular (PTS), dispositivo da Política Nacional de Humanização, é:', '["um conjunto de propostas de condutas terapêuticas articuladas, para um sujeito individual ou coletivo, resultado da discussão coletiva de uma equipe interdisciplinar.","a prescrição médica padronizada para todos os pacientes com o mesmo diagnóstico.","o protocolo de classificação de risco da UPA.","o regimento interno do Conselho Local de Saúde.","o plano de alta hospitalar definido exclusivamente pelo médico."]'::jsonb, 0, 'O PTS envolve diagnóstico, definição de metas, divisão de responsabilidades e reavaliação, com participação do usuário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-185', 'sus', null, 'Sobre a organização do controle social no SUS, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-186', 'sus', null, 'O Pacto pela Saúde (2006) estabeleceu, no Pacto pela Vida, prioridades sanitárias. Entre elas, inclui-se:', '["a saúde do idoso.","a privatização da atenção hospitalar.","o fim da Estratégia Saúde da Família.","a redução do controle social.","a centralização da gestão na União."]'::jsonb, 0, 'Prioridades do Pacto pela Vida incluíam saúde do idoso, controle do câncer de colo e de mama, redução da mortalidade infantil e materna, resposta às doenças emergentes, promoção da saúde e fortalecimento da Atenção Básica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-187', 'sus', null, 'Ao classificar um usuário na porta de urgência, a equipe utiliza um protocolo que prioriza o atendimento pela gravidade, e não pela ordem de chegada. Sobre o acolhimento com classificação de risco, é correto afirmar que:', '["ele qualifica a entrada do usuário e organiza o fluxo do atendimento conforme a gravidade do quadro.","ele ordena o atendimento pela ordem de chegada dos usuários.","ele se baseia exclusivamente na aferição de sinais vitais registrada na recepção por profissional administrativo.","ele dispensa a reavaliação do usuário enquanto aguarda atendimento.","ele é realizado apenas pelo médico plantonista."]'::jsonb, 0, 'A classificação de risco é feita por profissional de saúde capacitado (em geral, o enfermeiro), com reavaliações periódicas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-188', 'sus', null, 'O Sistema Nacional de Vigilância Sanitária é coordenado, no âmbito federal, pela:', '["Agência Nacional de Vigilância Sanitária (ANVISA).","Agência Nacional de Saúde Suplementar (ANS).","Fundação Nacional de Saúde (FUNASA).","Fundação Oswaldo Cruz (FIOCRUZ).","Secretaria de Atenção Primária à Saúde."]'::jsonb, 0, 'Lei 9.782/1999. A ANS regula os planos privados de saúde.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-189', 'sus', null, 'A Agência Nacional de Saúde Suplementar (ANS), criada pela Lei nº 9.961/2000, tem como finalidade:', '["regular, normatizar, controlar e fiscalizar as atividades das operadoras de planos privados de assistência à saúde.","executar ações de vigilância epidemiológica nos municípios.","coordenar a Rede de Atenção às Urgências.","registrar medicamentos e alimentos.","gerir os hospitais universitários federais."]'::jsonb, 0, 'O registro de medicamentos é atribuição da ANVISA.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-190', 'sus', null, 'No contexto da Política Nacional de Atenção Básica, a estratégia prioritária para expansão e consolidação da Atenção Básica é a:', '["Estratégia Saúde da Família.","Unidade de Pronto Atendimento.","atenção hospitalar de média complexidade.","rede de farmácias privadas conveniadas.","teleconsulta como única forma de atendimento."]'::jsonb, 0, 'A PNAB reconhece a Saúde da Família como estratégia prioritária, admitindo outras modalidades de equipe.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-191', 'sus', null, 'Considerando o financiamento e o planejamento no SUS, registre V para as afirmativas verdadeiras e F para as falsas.
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-192', 'sus', null, 'A Lei nº 13.427/2017 incluiu entre os princípios do SUS, no art. 7º da Lei nº 8.080/1990, a:', '["organização de atendimento público específico e especializado para mulheres e vítimas de violência doméstica em geral, incluindo atendimento psicológico e cirurgias plásticas reparadoras.","cobrança de taxa para atendimentos de média complexidade.","privatização dos serviços de atenção básica.","restrição do acesso a estrangeiros.","extinção dos Conselhos de Saúde."]'::jsonb, 0, 'O inciso reforça a integralidade e a equidade no atendimento às vítimas de violência.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-193', 'sus', null, 'Segundo a Lei nº 8.080/1990, a União poderá executar ações de vigilância epidemiológica e sanitária em circunstâncias especiais, como:', '["na ocorrência de agravos inusitados à saúde que possam escapar do controle da direção estadual do SUS ou que representem risco de disseminação nacional.","sempre que um município solicitar verba adicional.","em qualquer situação, substituindo os municípios permanentemente.","apenas em períodos eleitorais.","somente em hospitais privados."]'::jsonb, 0, 'Art. 16, parágrafo único, da Lei 8.080/90.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-194', 'sus', null, 'Segundo o Decreto nº 7.508/2011, a integralidade da assistência à saúde:', '["se inicia e se completa na Rede de Atenção à Saúde, mediante referenciamento do usuário na rede regional e interestadual.","se restringe à atenção primária.","é garantida apenas pelos hospitais de alta complexidade.","depende exclusivamente da iniciativa privada.","se encerra na Porta de Entrada."]'::jsonb, 0, 'Art. 20 do Decreto 7.508/2011.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-195', 'sus', null, 'Segundo a Lei nº 8.080/1990, o Subsistema de Atenção à Saúde Indígena tem como base os:', '["Distritos Sanitários Especiais Indígenas (DSEI).","Centros de Atenção Psicossocial.","Consórcios intermunicipais.","Conselhos Tutelares.","Hospitais universitários."]'::jsonb, 0, 'O subsistema é descentralizado, hierarquizado e regionalizado, considerando a realidade local e as especificidades culturais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-196', 'sus', null, 'Segundo a Lei nº 8.142/1990, o Conselho de Saúde é órgão colegiado composto por representantes:', '["do governo, dos prestadores de serviço, dos profissionais de saúde e dos usuários.","apenas do governo.","apenas dos usuários.","dos partidos políticos.","do Poder Judiciário e do Ministério Público."]'::jsonb, 0, 'A representação dos usuários é paritária em relação ao conjunto dos demais segmentos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-197', 'sus', null, 'O Estatuto da Pessoa com Deficiência (Lei nº 13.146/2015) assegura à pessoa com deficiência, entre outros direitos:', '["atendimento prioritário, inclusive nos serviços de saúde.","atendimento apenas em serviços especializados privados.","isenção de qualquer atendimento na Atenção Básica.","acesso à saúde condicionado à autorização familiar em todos os casos.","restrição de participação em ações de promoção da saúde."]'::jsonb, 0, 'O Estatuto assegura atenção integral à saúde em todos os níveis de complexidade, por intermédio do SUS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-198', 'sus', null, 'Segundo o Estatuto da Pessoa Idosa (Lei nº 10.741/2003), é vedada:', '["a discriminação da pessoa idosa nos planos de saúde pela cobrança de valores diferenciados em razão da idade.","a vacinação da pessoa idosa.","a presença de acompanhante para a pessoa idosa internada.","o atendimento domiciliar à pessoa idosa impossibilitada de se locomover.","a gratuidade de medicamentos de uso continuado."]'::jsonb, 0, 'O Estatuto assegura atenção integral à saúde da pessoa idosa, inclusive atendimento domiciliar quando necessário.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-199', 'sus', null, 'Segundo o Estatuto da Criança e do Adolescente, a vacinação das crianças nos casos recomendados pelas autoridades sanitárias é:', '["obrigatória.","facultativa, a critério da família.","proibida antes dos 2 anos.","condicionada à autorização judicial.","restrita às crianças matriculadas em escolas."]'::jsonb, 0, 'Art. 14, §1º, do ECA.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('sus-200', 'sus', null, 'A Política Nacional de Atenção Integral à Saúde das Pessoas Privadas de Liberdade no Sistema Prisional (PNAISP) tem como objetivo:', '["garantir o acesso dessas pessoas ao cuidado integral no SUS, com equipes de atenção primária prisional articuladas à rede.","restringir o atendimento a situações de urgência.","transferir a responsabilidade pela saúde ao sistema judiciário.","substituir o SUS por serviços privados nas unidades prisionais.","atender apenas presos condenados, excluindo os provisórios."]'::jsonb, 0, 'A política reafirma a universalidade e a equidade do SUS.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-001', 'tec', null, 'De acordo com a Lei nº 7.498/1986, é atividade PRIVATIVA do enfermeiro:', '["a consulta de enfermagem.","a verificação de sinais vitais.","a administração de medicamentos por via oral.","a realização de curativos simples.","a higiene e o conforto do paciente."]'::jsonb, 0, 'Art. 11, I: são privativas do enfermeiro, entre outras, a consulta de enfermagem, a prescrição da assistência de enfermagem e os cuidados de maior complexidade técnica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-002', 'tec', null, 'Segundo a Lei nº 7.498/1986, as atividades do técnico e do auxiliar de enfermagem, quando exercidas em instituições de saúde, somente podem ser desempenhadas:', '["sob orientação e supervisão de enfermeiro.","sob supervisão exclusiva do médico plantonista.","de forma totalmente autônoma.","com autorização do diretor administrativo.","sob supervisão do farmacêutico responsável."]'::jsonb, 0, 'Art. 15 da Lei 7.498/86.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-003', 'tec', null, 'O Código de Ética dos Profissionais de Enfermagem (Resolução COFEN nº 564/2017) prevê as seguintes penalidades, EXCETO:', '["detenção.","advertência verbal.","multa.","censura.","cassação do direito ao exercício profissional."]'::jsonb, 0, 'Penalidades do CEPE: advertência verbal, multa, censura, suspensão do exercício profissional e cassação. Detenção é pena criminal, não ética.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-004', 'tec', null, 'Segundo o Código de Ética (COFEN 564/2017), o profissional de enfermagem deve manter sigilo sobre fato de que tenha conhecimento em razão da atividade profissional, podendo revelá-lo:', '["nos casos previstos em lei, por ordem judicial ou com o consentimento escrito da pessoa envolvida ou de seu representante.","sempre que um familiar solicitar.","quando o paciente receber alta.","após o óbito do paciente, livremente.","em redes sociais, desde que sem foto."]'::jsonb, 0, 'O dever de sigilo permanece mesmo após o óbito; as exceções são lei, ordem judicial ou consentimento escrito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-005', 'tec', null, 'São momentos para a higiene das mãos preconizados pela OMS, EXCETO:', '["somente ao final do plantão.","antes de tocar o paciente.","antes de realizar procedimento limpo/asséptico.","após risco de exposição a fluidos corporais.","após tocar superfícies próximas ao paciente."]'::jsonb, 0, 'Os 5 momentos: antes de tocar o paciente, antes de procedimento limpo/asséptico, após risco de exposição a fluidos, após tocar o paciente e após tocar superfícies próximas a ele.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-006', 'tec', null, 'Para paciente com suspeita de tuberculose pulmonar bacilífera, a precaução indicada inclui:', '["precaução para aerossóis, com uso de máscara PFF2/N95 pelo profissional e quarto privativo (preferencialmente com pressão negativa).","apenas precaução padrão.","precaução para gotículas, com máscara cirúrgica para o profissional.","precaução de contato, com luvas e avental apenas.","isolamento reverso (protetor)."]'::jsonb, 0, 'TB, sarampo e varicela: precaução para aerossóis (PFF2/N95). O paciente, ao transitar, usa máscara cirúrgica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-007', 'tec', null, 'A precaução para gotículas (máscara cirúrgica a menos de 1 metro do paciente) está indicada em:', '["meningite meningocócica e influenza.","tuberculose pulmonar.","sarampo.","infecção por bactéria multirresistente em ferida.","escabiose."]'::jsonb, 0, 'Gotículas: meningite meningocócica, influenza, coqueluche, caxumba, rubéola. Escabiose e multirresistentes: contato. TB e sarampo: aerossóis.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-008', 'tec', null, 'Em relação ao manuseio de perfurocortantes (NR-32), é correto:', '["é vedado o reencape e a desconexão manual de agulhas.","deve-se reencapar a agulha com as duas mãos antes do descarte.","o coletor deve ser preenchido até a borda para evitar desperdício.","agulhas podem ser descartadas no lixo comum se protegidas com esparadrapo.","o coletor pode ser reutilizado após lavagem."]'::jsonb, 0, 'A NR-32 proíbe reencapar e desconectar agulhas manualmente. O coletor deve respeitar a linha de enchimento (cerca de 2/3).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-009', 'tec', null, 'Após acidente percutâneo com material biológico, a conduta imediata correta é:', '["lavar o local exaustivamente com água e sabão, sem espremer, e procurar atendimento para avaliação de profilaxia o quanto antes.","espremer o local para retirar o sangue e aplicar hipoclorito.","aplicar éter e aguardar o fim do plantão para notificar.","fazer incisão no local para aumentar o sangramento.","iniciar profilaxia somente após 72 horas, se houver sintomas."]'::jsonb, 0, 'Não se espreme nem se usa substância cáustica. A profilaxia pós-exposição ao HIV deve começar idealmente nas 2 primeiras horas (máximo de 72 h).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-010', 'tec', null, 'Um adulto em repouso com frequência cardíaca de 52 bpm apresenta:', '["bradicardia.","taquicardia.","normocardia.","bradipneia.","taquisfigmia."]'::jsonb, 0, 'FC normal do adulto: 60 a 100 bpm. Abaixo de 60 = bradicardia. Bradipneia refere-se à respiração.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-011', 'tec', null, 'Segundo as Diretrizes Brasileiras de Hipertensão Arterial (2020), um adulto com PA de 150 x 95 mmHg, confirmada, é classificado como:', '["hipertensão estágio 1.","pressão normal.","pré-hipertensão.","hipertensão estágio 2.","hipertensão estágio 3."]'::jsonb, 0, 'Estágio 1: PAS 140–159 e/ou PAD 90–99. Estágio 2: 160–179 / 100–109. Estágio 3: ≥180 / ≥110.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-012', 'tec', null, 'Na aferição da pressão arterial, é recomendado:', '["manter o braço apoiado na altura do coração, com o paciente sentado, bexiga vazia e após repouso.","aferir logo após o paciente fumar ou tomar café, para ter valor real.","usar manguito sempre do mesmo tamanho, independentemente da circunferência do braço.","manter o paciente com as pernas cruzadas.","posicionar o braço pendente abaixo do nível do coração."]'::jsonb, 0, 'Repouso de 3–5 minutos, sem fumar/cafeína nos 30 minutos anteriores, pernas descruzadas, manguito adequado à circunferência do braço.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-013', 'tec', null, 'Foram prescritos 500 mL de soro fisiológico 0,9% para correr em 4 horas, com equipo macrogotas. O gotejamento será de aproximadamente:', '["42 gotas/min.","21 gotas/min.","63 gotas/min.","125 gotas/min.","31 gotas/min."]'::jsonb, 0, 'Gotas/min = V ÷ (T × 3) = 500 ÷ (4 × 3) = 500 ÷ 12 ≈ 41,7 ≈ 42 gotas/min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-014', 'tec', null, 'Foram prescritos 300 mL de soro glicosado 5% para correr em 6 horas, com equipo microgotas. O gotejamento será de:', '["50 microgotas/min.","17 microgotas/min.","100 microgotas/min.","150 microgotas/min.","25 microgotas/min."]'::jsonb, 0, 'Microgotas/min = V ÷ T(h) = 300 ÷ 6 = 50 microgotas/min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-015', 'tec', null, 'Foram prescritos 250 mg de amoxicilina suspensão oral. O frasco contém 500 mg/5 mL. Deve-se administrar:', '["2,5 mL.","5 mL.","1 mL.","10 mL.","0,5 mL."]'::jsonb, 0, '500 mg — 5 mL; 250 mg — x → x = 2,5 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-016', 'tec', null, 'Prescrição: penicilina cristalina 2.000.000 UI. Frasco de 5.000.000 UI, diluído em 8 mL de água destilada (o pó acrescenta 2 mL, totalizando 10 mL). Deve-se aspirar:', '["4 mL.","2 mL.","3,2 mL.","5 mL.","8 mL."]'::jsonb, 0, '5.000.000 UI — 10 mL; 2.000.000 UI — x → x = 4 mL. Atenção: na penicilina cristalina considera-se o volume do soluto (2 mL).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-017', 'tec', null, 'Ao associar insulina regular e NPH na mesma seringa, deve-se:', '["aspirar primeiro a insulina regular (transparente) e depois a NPH (turva).","aspirar primeiro a NPH e depois a regular.","agitar vigorosamente os frascos antes de aspirar.","nunca associar as duas insulinas.","diluir ambas em soro fisiológico antes da aplicação."]'::jsonb, 0, 'Regular antes da NPH, para não contaminar o frasco de regular com NPH. A NPH deve ser homogeneizada rolando o frasco entre as mãos, sem agitar.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-018', 'tec', null, 'Para aplicação intramuscular de maior volume em adultos, a região considerada mais segura, por estar livre de grandes vasos e nervos, é a:', '["ventroglútea (Hochstetter).","deltoide.","dorsoglútea em qualquer quadrante.","face anterior do antebraço.","região abdominal."]'::jsonb, 0, 'A ventroglútea é a mais segura e comporta maiores volumes. O deltoide comporta pequenos volumes (até cerca de 2 mL).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-019', 'tec', null, 'A via intradérmica, utilizada por exemplo na vacina BCG e na prova tuberculínica, é feita com a agulha em ângulo de aproximadamente:', '["10 a 15 graus.","45 graus.","90 graus.","60 graus.","30 a 45 graus."]'::jsonb, 0, 'ID: 10–15°, com o bisel voltado para cima, formando pápula. SC: 45° ou 90°; IM: 90°.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-020', 'tec', null, 'NÃO faz parte dos "certos" da administração segura de medicamentos:', '["prescrição verbal sempre aceita sem registro.","paciente certo.","via certa.","dose certa.","registro certo."]'::jsonb, 0, 'Os 9 certos: paciente, medicamento, via, hora, dose, registro, orientação, forma e resposta. Prescrições verbais são restritas a urgências e devem ser registradas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-021', 'tec', null, 'A vacina BCG, segundo o PNI, é aplicada:', '["em dose única ao nascer, por via intradérmica, na inserção inferior do músculo deltoide direito.","aos 2 meses, por via intramuscular, no vasto lateral da coxa.","aos 12 meses, por via subcutânea.","em três doses, por via oral.","ao nascer, por via intramuscular, no glúteo."]'::jsonb, 0, 'BCG: dose única, preferencialmente ao nascer, ID, inserção inferior do deltoide direito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-022', 'tec', null, 'A primeira dose da vacina hepatite B no recém-nascido deve ser aplicada:', '["nas primeiras 24 horas de vida, preferencialmente nas primeiras 12 horas.","aos 2 meses de vida.","aos 6 meses de vida.","somente após o teste do pezinho.","aos 12 meses de vida."]'::jsonb, 0, 'Hepatite B ao nascer, IM, idealmente nas primeiras 12–24 horas, para prevenir a transmissão vertical.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-023', 'tec', null, 'Na rede de frio, as vacinas devem ser conservadas, nas instâncias locais (salas de vacina), na faixa de temperatura de:', '["+2 °C a +8 °C.","-20 °C a -10 °C.","0 °C a +2 °C.","+8 °C a +15 °C.","+15 °C a +25 °C."]'::jsonb, 0, 'Na sala de vacina a temperatura deve ficar entre +2 °C e +8 °C (ideal +5 °C).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-024', 'tec', null, 'Sobre a vacina rotavírus humano no calendário do PNI, é correto afirmar:', '["é administrada por via oral, aos 2 e 4 meses, respeitando idades máximas para cada dose.","é aplicada por via intramuscular aos 9 meses.","pode ser iniciada em qualquer idade da criança.","é aplicada em dose única ao nascer.","deve ser repetida anualmente."]'::jsonb, 0, 'Rotavírus: VO, 2 e 4 meses. Idade máxima: 1ª dose até 3 meses e 15 dias; 2ª dose até 7 meses e 29 dias.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-025', 'tec', null, 'A vacina tríplice viral (sarampo, caxumba e rubéola) é aplicada, no calendário infantil, aos:', '["12 meses, com a vacina tetraviral (ou SCR + varicela) aos 15 meses.","2 meses.","6 meses, em dose única.","4 anos, em dose única.","9 meses, junto com a hepatite B."]'::jsonb, 0, 'SCR aos 12 meses; aos 15 meses, a segunda dose de SCR + varicela (tetraviral).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-026', 'tec', null, 'Na ressuscitação cardiopulmonar do adulto, sem via aérea avançada, recomenda-se:', '["compressões de 100 a 120/min, com profundidade de 5 a 6 cm, na relação 30 compressões para 2 ventilações.","compressões de 60/min, com profundidade de 2 cm.","relação de 15 compressões para 1 ventilação.","compressões apenas após aplicar 5 ventilações de resgate.","interromper as compressões a cada 30 segundos para checar pulso."]'::jsonb, 0, 'Diretrizes AHA: 100–120/min, 5–6 cm, retorno total do tórax, mínimo de interrupções, 30:2.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-027', 'tec', null, 'São ritmos de parada cardiorrespiratória chocáveis com o desfibrilador:', '["fibrilação ventricular e taquicardia ventricular sem pulso.","assistolia e atividade elétrica sem pulso.","bradicardia sinusal e assistolia.","ritmo sinusal e fibrilação atrial.","apenas a assistolia."]'::jsonb, 0, 'FV e TV sem pulso são chocáveis. Assistolia e AESP não são chocáveis (tratam-se com RCP e adrenalina).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-028', 'tec', null, 'Pela regra dos nove, um adulto com queimadura nos dois membros superiores e em todo o tronco anterior tem superfície corporal queimada de:', '["36%.","18%.","27%.","45%.","54%."]'::jsonb, 0, 'Cada membro superior = 9% (9 + 9 = 18%) + tronco anterior = 18% → total 36%.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-029', 'tec', null, 'Paciente diabético consciente, com glicemia capilar de 55 mg/dL e capaz de deglutir. A conduta inicial adequada é:', '["oferecer cerca de 15 g de carboidrato de absorção rápida e repetir a glicemia em 15 minutos.","aplicar insulina regular imediatamente.","manter jejum e reavaliar em 2 horas.","oferecer refeição rica em gordura.","administrar glicose 50% IM."]'::jsonb, 0, 'Regra dos 15: 15 g de carboidrato simples, reavaliar após 15 minutos. Paciente inconsciente: glicose EV (ou glucagon).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-030', 'tec', null, 'Na Escala de Coma de Glasgow, a pontuação mínima e a máxima são, respectivamente:', '["3 e 15.","0 e 15.","1 e 10.","3 e 12.","5 e 20."]'::jsonb, 0, 'Glasgow: abertura ocular (1–4), resposta verbal (1–5), resposta motora (1–6). Total de 3 a 15; ≤ 8 sugere necessidade de via aérea definitiva.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-031', 'tec', null, 'No centro cirúrgico, a sala de operação é classificada como área:', '["restrita.","irrestrita.","semirrestrita.","de proteção.","administrativa."]'::jsonb, 0, 'Áreas: irrestrita (vestiários, acesso), semirrestrita (corredores internos, guarda de material) e restrita (salas de operação, lavabos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-032', 'tec', null, 'O indicador biológico utilizado para monitorar a esterilização por vapor saturado sob pressão (autoclave) contém esporos de:', '["Geobacillus stearothermophilus.","Escherichia coli.","Staphylococcus aureus.","Candida albicans.","Bacillus anthracis."]'::jsonb, 0, 'Autoclave a vapor: Geobacillus stearothermophilus. Óxido de etileno e calor seco: Bacillus atrophaeus.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-033', 'tec', null, 'Segundo a classificação de Spaulding, artigos que entram em contato com mucosas íntegras (como o laringoscópio) são considerados:', '["semicríticos, exigindo no mínimo desinfecção de alto nível.","críticos, exigindo esterilização obrigatoriamente.","não críticos, bastando limpeza.","descartáveis obrigatórios.","contaminados, devendo ser incinerados."]'::jsonb, 0, 'Críticos (penetram tecidos estéreis) → esterilização; semicríticos (mucosa íntegra/pele não íntegra) → desinfecção de alto nível ou esterilização; não críticos (pele íntegra) → limpeza/desinfecção de baixo nível.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-034', 'tec', null, 'Para a administração de enema (lavagem intestinal), a posição mais indicada é a:', '["de Sims (decúbito lateral esquerdo).","de Trendelenburg.","ginecológica.","prona.","de Fowler alta."]'::jsonb, 0, 'Na posição de Sims o líquido flui pela anatomia do sigmoide e do cólon descendente, à esquerda.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-035', 'tec', null, 'Na passagem de sonda nasogástrica em adulto, a medida do comprimento a ser introduzido é feita:', '["da ponta do nariz ao lóbulo da orelha e daí até o apêndice xifoide.","da boca até o umbigo.","do lóbulo da orelha até a cicatriz umbilical.","da ponta do nariz até o queixo.","do apêndice xifoide até a crista ilíaca."]'::jsonb, 0, 'Nariz → lóbulo da orelha → apêndice xifoide. A confirmação mais segura do posicionamento é radiológica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-036', 'tec', null, 'No cuidado com o cateterismo vesical de demora, é correto:', '["manter a bolsa coletora sempre abaixo do nível da bexiga e o sistema fechado.","elevar a bolsa acima da bexiga durante o transporte.","abrir o sistema diariamente para lavar a sonda.","realizar a inserção com técnica limpa, sem luvas estéreis.","esvaziar a bolsa somente quando estiver completamente cheia."]'::jsonb, 0, 'Inserção com técnica asséptica; sistema fechado; bolsa abaixo da bexiga e sem contato com o chão, esvaziada quando atingir cerca de 2/3.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-037', 'tec', null, 'O índice de Apgar avalia o recém-nascido no 1º e no 5º minuto de vida, considerando:', '["frequência cardíaca, esforço respiratório, tônus muscular, irritabilidade reflexa e cor.","peso, comprimento, perímetro cefálico, temperatura e glicemia.","reflexo de Moro, sucção, preensão, marcha e Babinski.","idade gestacional, peso, sexo, cor e choro.","pressão arterial, temperatura, saturação, glicemia e diurese."]'::jsonb, 0, 'Cada item vale de 0 a 2; total de 0 a 10. Apgar ≥ 7 no 5º minuto é considerado bom.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-038', 'tec', null, 'Segundo o Ministério da Saúde, o aleitamento materno deve ser:', '["exclusivo até os 6 meses e complementado até 2 anos ou mais.","exclusivo até os 4 meses e suspenso aos 12 meses.","exclusivo até os 2 anos.","complementado com água e chás desde o 1º mês.","substituído por fórmula a partir dos 3 meses."]'::jsonb, 0, 'Recomendação MS/OMS: exclusivo até 6 meses, sem água ou chás; complementado até 2 anos ou mais.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-039', 'tec', null, 'O teste do pezinho (triagem neonatal) deve ser realizado, idealmente, entre:', '["o 3º e o 5º dia de vida.","as primeiras 12 horas de vida.","o 15º e o 30º dia de vida.","o 2º e o 3º mês de vida.","somente após a primeira vacina."]'::jsonb, 0, 'A coleta entre o 3º e o 5º dia garante que o RN já se alimentou (necessário para a fenilcetonúria) e permite o diagnóstico precoce.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-040', 'tec', null, 'No puerpério imediato, os lóquios dos primeiros 3 a 4 dias, de coloração avermelhada, são denominados:', '["lóquios rubros (sanguíneos).","lóquios serosos.","lóquios brancos (alba).","colostro.","mecônio."]'::jsonb, 0, 'Evolução: rubros (1º–4º dia) → serosos/fuscos (até cerca de 10 dias) → brancos/alba. Odor fétido sugere infecção.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-041', 'tec', null, 'Conforme a Lei nº 10.216/2001, a internação psiquiátrica involuntária:', '["deve ser comunicada ao Ministério Público Estadual em até 72 horas.","é determinada exclusivamente pela Justiça.","dispensa laudo médico.","é solicitada pelo próprio paciente.","não precisa ser comunicada a nenhum órgão."]'::jsonb, 0, 'Tipos: voluntária (com consentimento), involuntária (sem consentimento, a pedido de terceiro, comunicada ao MP em 72 h) e compulsória (determinada pela Justiça). Todas exigem laudo médico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-042', 'tec', null, 'O serviço da Rede de Atenção Psicossocial que atende pessoas com problemas decorrentes do uso de álcool e outras drogas é o:', '["CAPS AD.","CAPS i.","CEO.","CEREST.","NASF."]'::jsonb, 0, 'CAPS AD: álcool e drogas; CAPS i: crianças e adolescentes; CEO: odontologia; CEREST: saúde do trabalhador.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-043', 'tec', null, 'É considerado sinal de alarme na dengue:', '["dor abdominal intensa e contínua.","febre de 38 °C no primeiro dia.","dor retro-orbitária.","mialgia leve.","exantema sem prurido."]'::jsonb, 0, 'Sinais de alarme: dor abdominal intensa, vômitos persistentes, acúmulo de líquidos, hipotensão postural, hepatomegalia > 2 cm, sangramento de mucosa, letargia/irritabilidade e aumento progressivo do hematócrito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-044', 'tec', null, 'O esquema básico de tratamento da tuberculose em adultos tem duração de:', '["6 meses: 2 meses de RHZE (fase intensiva) e 4 meses de RH (fase de manutenção).","2 meses de RHZE apenas.","12 meses de rifampicina isolada.","15 dias de antibiótico comum.","9 meses de isoniazida isolada."]'::jsonb, 0, '2RHZE/4RH (rifampicina, isoniazida, pirazinamida, etambutol). O Tratamento Diretamente Observado (TDO) é recomendado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-045', 'tec', null, 'As principais formas de transmissão da hepatite B são:', '["sexual, parenteral (sangue) e vertical.","fecal-oral, exclusivamente.","picada de mosquito.","contato com água contaminada.","aerossóis."]'::jsonb, 0, 'Hepatite B: sexual, parenteral e vertical. Hepatite A e E: fecal-oral. Prevenção: vacina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-046', 'tec', null, 'Para a identificação correta do paciente (meta 1 de segurança do paciente), recomenda-se utilizar no mínimo:', '["dois identificadores, como nome completo e data de nascimento.","o número do leito.","apenas o primeiro nome.","o diagnóstico médico.","a cor da pulseira, sem dados escritos."]'::jsonb, 0, 'Nunca usar número do leito ou do quarto como identificador. Usam-se ao menos dois identificadores na pulseira, conferidos antes de cada cuidado.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-047', 'tec', null, 'São metas internacionais de segurança do paciente, EXCETO:', '["aumentar o número de leitos hospitalares.","identificar corretamente o paciente.","melhorar a comunicação entre profissionais.","assegurar cirurgia segura.","reduzir o risco de quedas e de lesões por pressão."]'::jsonb, 0, 'As 6 metas: identificação, comunicação efetiva, segurança de medicamentos de alta vigilância, cirurgia segura, higiene das mãos (reduzir infecções) e redução de quedas e lesão por pressão.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-048', 'tec', null, 'A lesão por pressão com perda da pele em sua espessura parcial, com exposição da derme, leito vermelho/rosado e úmido, é classificada como estágio:', '["2.","1.","3.","4.","não classificável."]'::jsonb, 0, 'Estágio 1: pele íntegra com eritema que não embranquece; 2: perda parcial com exposição da derme; 3: perda total, gordura visível; 4: exposição de fáscia, músculo, tendão ou osso.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-049', 'tec', null, 'A escala de Braden é utilizada para avaliar:', '["o risco de desenvolvimento de lesão por pressão; quanto menor a pontuação, maior o risco.","o nível de consciência.","a intensidade da dor.","o risco de queda; quanto maior a pontuação, maior o risco.","o grau de dependência para atividades de vida diária."]'::jsonb, 0, 'Braden avalia percepção sensorial, umidade, atividade, mobilidade, nutrição e fricção/cisalhamento (6 a 23 pontos).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-050', 'tec', null, 'No cuidado com colostomia, ao recortar a placa da bolsa coletora, o orifício deve ser:', '["cerca de 2 a 3 mm maior que o diâmetro do estoma.","exatamente 2 cm maior que o estoma.","menor que o estoma, para comprimi-lo.","do mesmo tamanho do abdome.","irrelevante, pois a pele não sofre com o efluente."]'::jsonb, 0, 'Folga mínima (2–3 mm) protege a pele periestoma do contato com fezes sem garrotear o estoma.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-051', 'tec', null, 'Segundo a Lei nº 7.498/1986, o auxiliar de enfermagem exerce atividades de nível médio, de natureza repetitiva, envolvendo serviços auxiliares de enfermagem sob supervisão, cabendo-lhe especialmente:', '["observar, reconhecer e descrever sinais e sintomas.","realizar consulta de enfermagem.","prescrever a assistência de enfermagem.","planejar e avaliar os serviços de enfermagem.","realizar cuidados de maior complexidade técnica."]'::jsonb, 0, 'Art. 13 da Lei 7.498/86. As demais são privativas do enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-052', 'tec', null, 'Segundo a Lei nº 7.498/1986, a enfermagem é exercida privativamente por:', '["enfermeiro, técnico de enfermagem, auxiliar de enfermagem e parteira, legalmente habilitados e inscritos no Conselho Regional de Enfermagem.","qualquer pessoa com curso livre de cuidador.","médicos e enfermeiros apenas.","profissionais inscritos no Conselho Regional de Medicina.","estudantes de enfermagem, sem supervisão."]'::jsonb, 0, 'Arts. 1º e 2º: exercício livre em todo o território, observada a inscrição no COREN da respectiva região.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-053', 'tec', null, 'Segundo o Decreto nº 94.406/1987, cabe ao técnico de enfermagem, entre outras atividades:', '["assistir o enfermeiro na prestação de cuidados diretos a pacientes em estado grave.","realizar a consulta de enfermagem.","prescrever medicamentos estabelecidos em programas de saúde pública.","dirigir o serviço de enfermagem da instituição.","emitir parecer sobre matéria de enfermagem."]'::jsonb, 0, 'Art. 10 do Decreto 94.406/87. Prescrever em programas de saúde pública e emitir parecer são atribuições do enfermeiro.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-054', 'tec', null, 'Segundo o Código de Ética dos Profissionais de Enfermagem (COFEN 564/2017), é DIREITO do profissional:', '["recusar-se a executar atividades que não sejam de sua competência técnica, científica, ética e legal ou que não ofereçam segurança ao profissional, à pessoa, à família e à coletividade.","abandonar o plantão sem comunicar à chefia quando discordar da escala.","divulgar imagens de pacientes para fins educativos sem autorização.","executar prescrições de caráter duvidoso sem questionamento.","delegar suas atividades privativas a acompanhantes."]'::jsonb, 0, 'É direito previsto no CEPE. Abandonar o plantão e divulgar imagens sem autorização são infrações.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-055', 'tec', null, 'Segundo o Código de Ética (COFEN 564/2017), é PROIBIDO ao profissional de enfermagem:', '["administrar medicamentos sem conhecer indicação, ação da droga, via de administração e potenciais riscos.","registrar no prontuário as informações do cuidado prestado.","participar de movimentos de defesa da categoria.","atualizar seus conhecimentos técnicos e científicos.","comunicar ao COREN fatos que infrinjam o Código."]'::jsonb, 0, 'O desconhecimento do medicamento expõe o paciente a risco; as demais condutas são deveres ou direitos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-056', 'tec', null, 'Segundo o Código de Ética (COFEN 564/2017), é proibido registrar no prontuário:', '["informações incompletas, imprecisas ou inverídicas sobre a assistência prestada.","o horário dos procedimentos realizados.","as intercorrências do plantão.","a assinatura e o número de inscrição no COREN.","as orientações dadas ao paciente."]'::jsonb, 0, 'Os registros devem ser claros, objetivos, cronológicos, legíveis, completos e sem rasuras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-057', 'tec', null, 'Ao cometer um erro durante a anotação de enfermagem em prontuário físico, o profissional deve:', '["não rasurar nem usar corretivo, sinalizando o engano (por exemplo, com a expressão \"digo\") e escrevendo a informação correta em seguida.","usar corretivo líquido e reescrever.","arrancar a folha e refazer todo o registro.","riscar até ficar ilegível.","pedir que outro profissional reescreva com sua assinatura."]'::jsonb, 0, 'Rasuras comprometem o valor legal do prontuário; a correção deve ser transparente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-058', 'tec', null, 'Segundo o Código de Ética (COFEN 564/2017), a penalidade de suspensão consiste na proibição do exercício profissional por período de até:', '["90 dias.","30 dias.","1 ano.","5 anos.","30 anos."]'::jsonb, 0, 'Suspensão: até 90 dias. A cassação é a perda do direito ao exercício por até 30 anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-059', 'tec', null, 'Segundo o Código de Ética (COFEN 564/2017), a advertência verbal consiste:', '["na admoestação ao infrator, de forma reservada, registrada em seu prontuário, na presença de duas testemunhas.","na publicação do nome do infrator em jornal de grande circulação.","no pagamento de multa equivalente a uma anuidade.","na proibição do exercício por 30 dias.","na perda definitiva do registro profissional."]'::jsonb, 0, 'É a penalidade mais branda do CEPE.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-060', 'tec', null, 'Segundo o Código de Ética (COFEN 564/2017), a penalidade de multa consiste no pagamento de:', '["1 a 10 vezes o valor da anuidade da categoria profissional.","1 salário mínimo, fixo.","50% do salário do profissional.","10 a 20 vezes o valor da anuidade.","valor definido pelo empregador."]'::jsonb, 0, 'Multa: de 01 a 10 vezes o valor da anuidade à qual pertence o infrator.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-061', 'tec', null, 'O técnico de enfermagem que administra medicamento por via endovenosa sem ter sido treinado para a técnica, causando dano ao paciente, age com:', '["imperícia.","imprudência.","negligência.","dolo.","omissão de socorro."]'::jsonb, 0, 'Imperícia = falta de habilidade ou conhecimento técnico. Imprudência = agir com precipitação. Negligência = omissão, descuido.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-062', 'tec', null, 'Deixar de elevar as grades da cama de um paciente confuso, que vem a cair, caracteriza:', '["negligência.","imperícia.","imprudência.","caso fortuito.","conduta ética adequada."]'::jsonb, 0, 'Negligência é a omissão de um cuidado devido.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-063', 'tec', null, 'Na precaução padrão, que deve ser aplicada a todos os pacientes, o uso de óculos de proteção e máscara cirúrgica está indicado:', '["quando houver risco de respingos de sangue ou secreções na face.","somente em pacientes com HIV.","apenas em isolamento de aerossóis.","em nenhuma situação.","apenas durante a administração de medicamentos orais."]'::jsonb, 0, 'A precaução padrão independe do diagnóstico: luvas, avental, máscara e óculos conforme o risco de exposição.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-064', 'tec', null, 'Na retirada dos EPIs após atendimento a paciente em precaução de contato, o primeiro item a ser retirado, em regra, é:', '["as luvas.","a máscara.","o gorro.","os óculos.","o propé."]'::jsonb, 0, 'As luvas são as mais contaminadas e saem primeiro; a higiene das mãos é feita ao final (e entre etapas, se necessário).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-065', 'tec', null, 'A duração recomendada para a fricção antisséptica das mãos com preparação alcoólica é de:', '["20 a 30 segundos.","5 segundos.","40 a 60 segundos.","2 minutos.","5 minutos."]'::jsonb, 0, 'Fricção com álcool: 20–30 s. Lavagem com água e sabão: 40–60 s.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-066', 'tec', null, 'A higiene das mãos com água e sabão (e não apenas com álcool) é obrigatória quando:', '["as mãos estiverem visivelmente sujas ou após contato com paciente com infecção por Clostridioides difficile.","o profissional for administrar medicação oral.","o paciente estiver em precaução padrão.","o álcool estiver disponível à beira do leito.","o profissional usar luvas de procedimento."]'::jsonb, 0, 'O álcool não remove sujidade visível nem é eficaz contra esporos de C. difficile.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-067', 'tec', null, 'Segundo a RDC ANVISA nº 222/2018, os resíduos perfurocortantes (agulhas, lâminas, ampolas de vidro) pertencem ao grupo:', '["E.","A.","B.","C.","D."]'::jsonb, 0, 'A: infectantes; B: químicos; C: radioativos; D: comuns; E: perfurocortantes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-068', 'tec', null, 'Segundo a RDC nº 222/2018, os resíduos com possível presença de agentes biológicos (grupo A) devem ser acondicionados em:', '["saco branco leitoso, com símbolo de substância infectante.","saco preto comum.","saco azul para recicláveis.","caixa de papelão comum.","recipiente de vidro."]'::jsonb, 0, 'Grupo A: saco branco leitoso, resistente, identificado com o símbolo de risco biológico.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-069', 'tec', null, 'Os resíduos de medicamentos quimioterápicos e de produtos químicos perigosos pertencem, segundo a RDC nº 222/2018, ao grupo:', '["B.","A.","C.","D.","E."]'::jsonb, 0, 'Grupo B: resíduos químicos que apresentam risco à saúde ou ao meio ambiente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-070', 'tec', null, 'A concentração de álcool etílico com melhor ação antisséptica e desinfetante é:', '["70%.","46%.","92,8%.","99%.","30%."]'::jsonb, 0, 'O álcool a 70% tem a água necessária para desnaturar proteínas microbianas; concentrações muito altas evaporam rápido e são menos eficazes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-071', 'tec', null, 'A limpeza terminal de uma unidade de internação deve ser realizada:', '["após alta, óbito ou transferência do paciente, ou em internações prolongadas, conforme protocolo.","várias vezes ao dia, com o paciente no leito.","apenas quando houver sujeira visível.","somente uma vez por ano.","apenas em unidades de terapia intensiva."]'::jsonb, 0, 'A limpeza concorrente é diária, com o paciente internado; a terminal é completa, após a desocupação do leito.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-072', 'tec', null, 'Durante a limpeza de superfícies hospitalares, deve-se seguir o sentido:', '["do mais limpo para o mais sujo e de cima para baixo.","do mais sujo para o mais limpo.","de baixo para cima.","aleatório, desde que use desinfetante.","do chão para o teto."]'::jsonb, 0, 'Esse sentido evita espalhar sujidade e contaminação para áreas já limpas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-073', 'tec', null, 'Para profissionais de saúde, é recomendada a vacinação contra hepatite B com:', '["3 doses e posterior verificação da soroconversão (anti-HBs).","dose única, sem necessidade de avaliação.","2 doses com intervalo de 1 ano.","reforço anual.","apenas após acidente com material biológico."]'::jsonb, 0, 'O anti-HBs (1 a 2 meses após a última dose) confirma a resposta vacinal; não respondedores repetem o esquema.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-074', 'tec', null, 'Na precaução de contato, recomenda-se:', '["uso de luvas e avental durante o contato com o paciente e seu ambiente, e artigos como estetoscópio de uso exclusivo.","máscara PFF2 obrigatória para qualquer contato.","quarto com pressão negativa.","apenas higiene das mãos, sem outros EPIs.","uso de máscara cirúrgica pelo paciente durante todo o tempo."]'::jsonb, 0, 'Indicada, por exemplo, para bactérias multirresistentes, C. difficile e escabiose.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-075', 'tec', null, 'Ao abrir um pacote estéril sobre uma superfície, a primeira aba deve ser aberta:', '["para o lado oposto ao corpo do profissional.","em direção ao corpo do profissional.","tocando a parte interna com as mãos.","por um acompanhante.","com as mãos molhadas."]'::jsonb, 0, 'Abrir a primeira aba para longe evita passar o braço sobre a área estéril exposta.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-076', 'tec', null, 'Em adultos, o pulso recomendado para checagem durante o atendimento de uma parada cardiorrespiratória é o:', '["carotídeo.","radial.","pedioso.","temporal.","poplíteo."]'::jsonb, 0, 'Em adultos, carotídeo (ou femoral). Em lactentes, braquial.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-077', 'tec', null, 'Em lactentes, durante a avaliação de uma possível parada cardiorrespiratória, o pulso a ser checado é o:', '["braquial.","carotídeo.","radial.","pedioso.","temporal."]'::jsonb, 0, 'O pescoço curto do lactente dificulta a palpação do pulso carotídeo.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-078', 'tec', null, 'O padrão respiratório caracterizado por ciclos de aumento e diminuição progressivos da amplitude, intercalados com períodos de apneia, é denominado:', '["Cheyne-Stokes.","Kussmaul.","Biot.","eupneia.","taquipneia."]'::jsonb, 0, 'Comum na insuficiência cardíaca grave e em lesões neurológicas. Biot é irregular, sem padrão crescente-decrescente.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-079', 'tec', null, 'A respiração profunda e rápida, típica da cetoacidose diabética, é chamada de respiração de:', '["Kussmaul.","Cheyne-Stokes.","Biot.","bradipneia.","apneia."]'::jsonb, 0, 'É um mecanismo compensatório para eliminar CO2 na acidose metabólica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-080', 'tec', null, 'A dificuldade de respirar na posição deitada, que melhora quando o paciente se senta, é chamada de:', '["ortopneia.","bradipneia.","apneia.","eupneia.","hiperpneia."]'::jsonb, 0, 'Característica da insuficiência cardíaca congestiva.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-081', 'tec', null, 'Considera-se hipotensão ortostática a queda, até 3 minutos após o paciente ficar em pé, de:', '["20 mmHg ou mais na pressão sistólica e/ou 10 mmHg ou mais na diastólica.","5 mmHg na sistólica.","qualquer variação de pressão.","50 mmHg na diastólica, apenas.","aumento de 20 mmHg na sistólica."]'::jsonb, 0, 'Comum em idosos, desidratados e em uso de anti-hipertensivos; aumenta o risco de queda.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-082', 'tec', null, 'Na aferição da pressão arterial pelo método auscultatório, o primeiro som audível (fase I de Korotkoff) corresponde à:', '["pressão sistólica.","pressão diastólica.","pressão média.","frequência cardíaca.","pressão de pulso."]'::jsonb, 0, 'Fase I = PAS; desaparecimento dos sons (fase V) = PAD.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-083', 'tec', null, 'A dor é considerada atualmente o "quinto sinal vital". Em pacientes adultos comunicativos, um instrumento simples para mensurá-la é:', '["a escala numérica de 0 a 10.","a escala de Glasgow.","a escala de Braden.","a escala de Morse.","o índice de Apgar."]'::jsonb, 0, 'Também se usam a escala visual analógica e a de faces.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-084', 'tec', null, 'Para a verificação da glicemia capilar, a punção deve ser realizada preferencialmente:', '["na face lateral da polpa digital.","no centro da polpa digital.","no lóbulo da orelha, sempre.","na região do calcanhar em adultos.","na veia do dorso da mão."]'::jsonb, 0, 'A lateral é menos dolorosa e tem boa vascularização; fazer rodízio dos dedos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-085', 'tec', null, 'Em um balanço hídrico de 24 horas, o paciente recebeu 2.000 mL (soro e dieta) e eliminou 1.500 mL (diurese e dreno). O balanço é:', '["positivo em 500 mL.","negativo em 500 mL.","positivo em 3.500 mL.","negativo em 3.500 mL.","neutro."]'::jsonb, 0, 'Balanço = ganhos − perdas = 2.000 − 1.500 = +500 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-086', 'tec', null, 'A posição de Fowler, com a cabeceira elevada (geralmente entre 45° e 60°), é indicada principalmente para:', '["pacientes com dispneia, para facilitar a expansão pulmonar.","realização de enema.","exame ginecológico.","pacientes em choque, para elevar os membros inferiores.","cirurgias da coluna."]'::jsonb, 0, 'A elevação reduz a pressão das vísceras sobre o diafragma.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-087', 'tec', null, 'Na posição de Trendelenburg, o paciente fica em decúbito dorsal com:', '["a cabeça mais baixa que os pés.","a cabeceira elevada a 90°.","o corpo lateralizado à esquerda.","as pernas flexionadas e abduzidas em perneiras.","o corpo em decúbito ventral."]'::jsonb, 0, 'Usada em algumas cirurgias pélvicas e abdominais baixas. Litotomia é com as pernas em perneiras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-088', 'tec', null, 'Para prevenir lesão por pressão em paciente acamado, recomenda-se mudança de decúbito, em geral, a cada:', '["2 horas, ajustando conforme avaliação de risco.","12 horas.","24 horas.","6 horas, apenas no período diurno.","não é necessário em colchão comum."]'::jsonb, 0, 'O intervalo é individualizado, mas 2 h é a referência clássica; superfícies especiais complementam.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-089', 'tec', null, 'Na oxigenoterapia por cateter nasal tipo óculos, o fluxo máximo usual, para evitar ressecamento e desconforto, é de aproximadamente:', '["6 L/min.","15 L/min.","20 L/min.","30 L/min.","50 L/min."]'::jsonb, 0, 'Fluxos maiores exigem máscara (simples, Venturi ou com reservatório).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-090', 'tec', null, 'No umidificador de oxigênio, deve-se utilizar:', '["água destilada estéril, respeitando o nível indicado.","soro glicosado.","água da torneira.","álcool 70%.","água oxigenada."]'::jsonb, 0, 'A água estéril reduz o risco de contaminação das vias aéreas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-091', 'tec', null, 'O dispositivo de oxigenoterapia que permite oferecer uma fração inspirada de oxigênio (FiO2) precisa e controlada é:', '["a máscara de Venturi.","o cateter nasal.","a máscara simples.","a tenda facial.","o ambu sem reservatório."]'::jsonb, 0, 'As válvulas coloridas da Venturi definem a FiO2 (por exemplo, 24% a 50%).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-092', 'tec', null, 'Na aspiração de secreções de vias aéreas, cada sucção deve durar, no máximo, cerca de:', '["10 a 15 segundos.","1 minuto.","2 minutos.","30 segundos contínuos, sempre.","não há limite de tempo."]'::jsonb, 0, 'Sucções longas causam hipoxemia; aplicar a pressão negativa apenas na retirada da sonda.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-093', 'tec', null, 'No banho no leito, a sequência correta da higiene é:', '["do mais limpo para o mais sujo, deixando a região genital e perianal por último.","começar pela região perianal.","lavar os pés antes do rosto.","usar a mesma água do início ao fim, sem trocar.","não é necessário secar a pele."]'::jsonb, 0, 'Segue-se do rosto para os pés, com troca da água quando necessário e secagem cuidadosa, especialmente das dobras.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-094', 'tec', null, 'Na higiene oral de paciente inconsciente, para reduzir o risco de broncoaspiração, deve-se:', '["posicioná-lo em decúbito lateral, com a cabeça lateralizada.","colocá-lo em decúbito dorsal horizontal.","usar grande quantidade de água na cavidade oral.","introduzir os dedos sem proteção.","colocá-lo em Trendelenburg."]'::jsonb, 0, 'A lateralização facilita o escoamento de líquidos e secreções.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-095', 'tec', null, 'Após o óbito de paciente cuja morte será investigada pelo Instituto Médico Legal (morte violenta ou suspeita), o preparo do corpo deve:', '["manter sondas, drenos e cateteres no lugar, conforme orientação da instituição.","retirar todos os dispositivos e lavar o corpo.","realizar tamponamento de todas as feridas e retirar as roupas.","descartar as roupas e os pertences.","aplicar maquiagem para identificação."]'::jsonb, 0, 'Em casos de IML, dispositivos e vestígios devem ser preservados para a perícia.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-096', 'tec', null, 'Foram prescritos 0,5 g de um medicamento por via oral. Há comprimidos de 250 mg. Deve-se administrar:', '["2 comprimidos.","1/2 comprimido.","1 comprimido.","4 comprimidos.","5 comprimidos."]'::jsonb, 0, '0,5 g = 500 mg; 500 ÷ 250 = 2 comprimidos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-097', 'tec', null, 'Foram prescritos 500 mg de dipirona EV. A ampola contém 1 g em 2 mL. Deve-se aspirar:', '["1 mL.","0,5 mL.","2 mL.","1,5 mL.","0,25 mL."]'::jsonb, 0, '1.000 mg — 2 mL; 500 mg — x → x = 1 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-098', 'tec', null, 'Foram prescritos 40 mg de furosemida EV. A ampola contém 20 mg em 2 mL. Deve-se administrar:', '["4 mL.","2 mL.","1 mL.","8 mL.","0,4 mL."]'::jsonb, 0, '20 mg — 2 mL; 40 mg — x → x = 4 mL (duas ampolas).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-099', 'tec', null, 'Um frasco de cefalotina 1 g foi diluído em 10 mL. Para administrar 750 mg, deve-se aspirar:', '["7,5 mL.","7 mL.","5 mL.","0,75 mL.","75 mL."]'::jsonb, 0, '1.000 mg — 10 mL; 750 mg — x → x = 7,5 mL.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-100', 'tec', null, 'Foram prescritos 1.000 mL de soro fisiológico para correr em 12 horas, com equipo macrogotas. O gotejamento será de aproximadamente:', '["28 gotas/min.","83 gotas/min.","14 gotas/min.","42 gotas/min.","56 gotas/min."]'::jsonb, 0, 'Gotas/min = V ÷ (T × 3) = 1.000 ÷ 36 ≈ 27,8 ≈ 28 gotas/min.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-101', 'tec', null, 'Quanto às equivalências usadas no cálculo de gotejamento, é correto afirmar:', '["1 mL = 20 gotas = 60 microgotas.","1 mL = 10 gotas = 20 microgotas.","1 gota = 1 microgota.","1 mL = 60 gotas = 20 microgotas.","1 mL = 100 microgotas."]'::jsonb, 0, '1 gota corresponde a 3 microgotas; 1 mL = 20 gotas = 60 microgotas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-102', 'tec', null, 'Um antibiótico diluído em 100 mL deve correr em 30 minutos, com equipo macrogotas. O gotejamento será de aproximadamente:', '["67 gotas/min.","33 gotas/min.","100 gotas/min.","200 gotas/min.","20 gotas/min."]'::jsonb, 0, 'Para tempo em minutos: gotas/min = (V × 20) ÷ min = (100 × 20) ÷ 30 ≈ 66,7 ≈ 67.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-103', 'tec', null, 'Foram prescritos 500 mL de soro para correr em 8 horas em bomba de infusão. A vazão a ser programada é de:', '["62,5 mL/h.","40 mL/h.","125 mL/h.","21 mL/h.","80 mL/h."]'::jsonb, 0, 'mL/h = volume ÷ tempo = 500 ÷ 8 = 62,5 mL/h.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-104', 'tec', null, 'Um frasco de 500 mL de soro glicosado a 5% contém:', '["25 g de glicose.","5 g de glicose.","50 g de glicose.","2,5 g de glicose.","250 g de glicose."]'::jsonb, 0, '5% = 5 g em 100 mL → em 500 mL há 25 g.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-105', 'tec', null, 'Um frasco de 500 mL de soro fisiológico a 0,9% contém de cloreto de sódio:', '["4,5 g.","0,9 g.","9 g.","45 g.","0,45 g."]'::jsonb, 0, '0,9% = 0,9 g em 100 mL → 500 mL contêm 4,5 g.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-106', 'tec', null, 'Foram prescritas 30 UI de insulina NPH. Só há disponível seringa de 3 mL (sem escala em UI) e o frasco é de 100 UI/mL. Deve-se aspirar:', '["0,3 mL.","3 mL.","0,03 mL.","1 mL.","30 mL."]'::jsonb, 0, '100 UI — 1 mL; 30 UI — x → x = 0,3 mL. O ideal, porém, é sempre usar seringa de insulina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-107', 'tec', null, 'Na aplicação de insulina subcutânea, o rodízio dos locais de aplicação tem como principal objetivo:', '["prevenir lipodistrofias, que alteram a absorção da insulina.","aumentar a dor para o paciente perceber a aplicação.","acelerar o efeito da insulina NPH.","evitar a necessidade de higiene das mãos.","dispensar a verificação da glicemia."]'::jsonb, 0, 'Aplicações repetidas no mesmo ponto causam lipo-hipertrofia e absorção irregular.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-108', 'tec', null, 'Na aplicação de heparina por via subcutânea, recomenda-se:', '["não aspirar e não massagear o local após a aplicação.","aspirar antes de injetar e massagear vigorosamente.","aplicar por via intramuscular quando o paciente for magro.","aplicar sempre no deltoide.","aquecer o medicamento antes."]'::jsonb, 0, 'Aspirar e massagear aumentam o risco de hematoma.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-109', 'tec', null, 'A principal vantagem da via sublingual é:', '["a absorção rápida, sem passar pelo metabolismo de primeira passagem hepática.","a possibilidade de administrar grandes volumes.","o efeito exclusivamente local na boca.","a absorção lenta e prolongada.","dispensar a orientação do paciente."]'::jsonb, 0, 'Exemplo clássico: nitratos na angina.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-110', 'tec', null, 'A técnica de aplicação intramuscular em "Z" (zigue-zague) é indicada principalmente para:', '["medicamentos irritantes ou que mancham a pele, como o ferro, evitando refluxo para o subcutâneo.","vacinas intradérmicas.","insulinas.","medicamentos orais.","administração em lactentes, obrigatoriamente."]'::jsonb, 0, 'O deslocamento lateral da pele cria um trajeto que se fecha após a retirada da agulha.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-111', 'tec', null, 'Em lactentes, a região preferencial para a aplicação de injeções intramusculares é:', '["o vasto lateral da coxa.","o deltoide.","a dorsoglútea.","o abdome.","o antebraço."]'::jsonb, 0, 'O vasto lateral é o músculo mais desenvolvido no lactente e está longe de grandes vasos e nervos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-112', 'tec', null, 'Um paciente com acesso venoso periférico apresenta dor, calor, rubor e edema ao longo do trajeto da veia. Trata-se de:', '["flebite; a conduta inclui retirar o cateter e comunicar o enfermeiro.","reação normal, sem necessidade de intervenção.","infiltração; deve-se aumentar o gotejamento.","embolia gasosa.","hipoglicemia."]'::jsonb, 0, 'A flebite é inflamação da veia; o local deve ser monitorado e registrado, com novo acesso em outro sítio.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-113', 'tec', null, 'Na administração de medicamentos por sonda nasoenteral, é correto:', '["lavar a sonda com água antes e após cada medicamento e não triturar comprimidos de liberação prolongada ou revestimento entérico.","misturar todos os medicamentos na dieta enteral.","triturar qualquer comprimido, inclusive de liberação prolongada.","administrar sem lavar a sonda.","usar sempre soro glicosado para lavar a sonda."]'::jsonb, 0, 'Liberação controlada, se triturada, pode causar dose tóxica imediata; misturar à dieta favorece obstrução e interações.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-114', 'tec', null, 'Os antibióticos devem ser administrados rigorosamente nos horários prescritos, principalmente para:', '["manter o nível sérico terapêutico do medicamento.","facilitar a organização da escala.","evitar a perda do equipo.","reduzir o custo do tratamento.","permitir o uso de doses menores."]'::jsonb, 0, 'Atrasos reduzem a concentração do fármaco e favorecem resistência bacteriana.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-115', 'tec', null, 'A penicilina G benzatina deve ser administrada exclusivamente por via:', '["intramuscular profunda (por exemplo, ventroglútea ou dorsoglútea).","endovenosa.","subcutânea.","intradérmica.","oral."]'::jsonb, 0, 'É uma suspensão; a administração endovenosa pode causar embolia e morte.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-116', 'tec', null, 'Na anafilaxia, o medicamento de primeira escolha é:', '["adrenalina por via intramuscular (vasto lateral da coxa).","dipirona endovenosa.","anti-histamínico oral.","corticoide inalatório.","soro glicosado."]'::jsonb, 0, 'A adrenalina IM deve ser dada imediatamente; anti-histamínicos e corticoides são adjuvantes.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-117', 'tec', null, 'Antes de administrar digoxina a um adulto, o profissional deve verificar a frequência cardíaca, e não administrar e comunicar se ela estiver:', '["abaixo de 60 bpm.","acima de 60 bpm.","entre 70 e 90 bpm.","acima de 80 bpm.","não é necessário verificar."]'::jsonb, 0, 'A digoxina reduz a FC; bradicardia pode indicar intoxicação digitálica.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-118', 'tec', null, 'O antídoto da heparina é:', '["sulfato de protamina.","vitamina K.","naloxona.","flumazenil.","atropina."]'::jsonb, 0, 'Varfarina: vitamina K; opioides: naloxona; benzodiazepínicos: flumazenil.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-119', 'tec', null, 'Para paciente em uso de varfarina, o exame que deve ser monitorado é:', '["o tempo de protrombina, expresso em RNI (INR).","a glicemia.","o hemograma, apenas.","a ureia.","o colesterol total."]'::jsonb, 0, 'Em caso de sangramento por excesso de varfarina, o antídoto é a vitamina K.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-120', 'tec', null, 'Na depressão respiratória por intoxicação com opioides (por exemplo, morfina), o antídoto indicado é:', '["naloxona.","flumazenil.","protamina.","vitamina K.","gluconato de cálcio."]'::jsonb, 0, 'A naloxona é antagonista dos receptores opioides.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-121', 'tec', null, 'O flumazenil é o antídoto utilizado na intoxicação por:', '["benzodiazepínicos.","opioides.","heparina.","paracetamol.","organofosforados."]'::jsonb, 0, 'Exemplos de benzodiazepínicos: diazepam e midazolam.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-122', 'tec', null, 'O nitroprussiato de sódio, na infusão contínua, exige o cuidado de:', '["proteger a solução e o equipo da luz (fotossensível).","aquecer a solução a 40 °C.","agitar o frasco a cada hora.","administrar em bolus rápido.","diluir em água destilada para uso intramuscular."]'::jsonb, 0, 'A luz degrada o nitroprussiato; também exige bomba de infusão e monitorização da PA.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-123', 'tec', null, 'A vacina pentavalente, aplicada aos 2, 4 e 6 meses, protege contra:', '["difteria, tétano, coqueluche, Haemophilus influenzae tipo b e hepatite B.","sarampo, caxumba, rubéola, varicela e febre amarela.","poliomielite, rotavírus, hepatite A, meningite C e influenza.","tuberculose, hepatite B, tétano, difteria e sarampo.","HPV, hepatite A, hepatite B, febre amarela e dengue."]'::jsonb, 0, 'Pentavalente = DTP + Hib + hepatite B.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-124', 'tec', null, 'No calendário infantil do PNI, a vacina pneumocócica 10-valente é aplicada:', '["aos 2 e 4 meses, com reforço aos 12 meses.","ao nascer, em dose única.","aos 9 meses e aos 4 anos.","aos 15 meses, em dose única.","anualmente, a partir dos 6 meses."]'::jsonb, 0, 'Esquema básico de 2 doses + reforço aos 12 meses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-125', 'tec', null, 'No calendário infantil do PNI, as doses do esquema básico da vacina meningocócica C conjugada são aplicadas aos:', '["3 e 5 meses.","2 e 4 meses.","6 e 9 meses.","12 e 15 meses.","ao nascer e aos 2 meses."]'::jsonb, 0, 'O esquema básico é aos 3 e 5 meses, com reforço no 2º ano de vida.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-126', 'tec', null, 'Com a atualização do calendário em 2024, a vacina oral contra poliomielite (VOP) foi substituída, no reforço dos 15 meses, pela:', '["vacina inativada poliomielite (VIP), por via intramuscular.","vacina pentavalente.","vacina rotavírus.","vacina tríplice viral.","vacina BCG."]'::jsonb, 0, 'O esquema passou a ser totalmente com VIP: 2, 4 e 6 meses + reforço aos 15 meses.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-127', 'tec', null, 'Os reforços da vacina DTP (tríplice bacteriana) no calendário infantil são feitos aos:', '["15 meses e 4 anos.","6 meses e 1 ano.","9 meses e 15 meses.","2 anos e 10 anos.","4 e 9 anos."]'::jsonb, 0, 'Depois, o adulto mantém reforço de dT a cada 10 anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-128', 'tec', null, 'A vacina hepatite A, no calendário infantil do PNI, é aplicada:', '["aos 15 meses, em dose única.","ao nascer.","aos 2, 4 e 6 meses.","aos 9 meses e aos 4 anos.","aos 11 anos."]'::jsonb, 0, 'Dose única aos 15 meses (pode ser aplicada até 4 anos, 11 meses e 29 dias).') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-129', 'tec', null, 'Para adultos com esquema básico completo, o reforço da vacina dupla adulto (dT) deve ser feito a cada:', '["10 anos.","1 ano.","3 anos.","5 anos, obrigatoriamente.","20 anos."]'::jsonb, 0, 'Em ferimentos graves, o reforço pode ser antecipado se a última dose tiver mais de 5 anos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-130', 'tec', null, 'Crianças de 6 meses a menores de 9 anos que recebem a vacina influenza pela primeira vez devem receber:', '["2 doses, com intervalo de 30 dias.","1 dose apenas.","3 doses, com intervalo de 7 dias.","dose dupla em uma única aplicação.","nenhuma dose, pois é contraindicada."]'::jsonb, 0, 'A primovacinação em crianças exige 2 doses; nos anos seguintes, dose anual única.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-131', 'tec', null, 'Em crianças menores de 2 anos, as vacinas febre amarela e tríplice viral:', '["não devem ser administradas no mesmo dia, respeitando intervalo de 30 dias entre elas.","devem ser obrigatoriamente aplicadas juntas.","podem ser aplicadas com qualquer intervalo.","são contraindicadas antes dos 5 anos.","devem ter intervalo de 1 ano."]'::jsonb, 0, 'A coadministração nessa faixa etária reduz a resposta imune a ambas.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-132', 'tec', null, 'São exemplos de vacinas de vírus ou bactérias vivos atenuados:', '["BCG, rotavírus, tríplice viral e febre amarela.","hepatite B, dT e influenza.","pentavalente, VIP e pneumocócica.","HPV, hepatite A e meningocócica C.","dTpa, raiva e hepatite B."]'::jsonb, 0, 'Vacinas vivas exigem cuidado em gestantes e imunodeprimidos.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-133', 'tec', null, 'Constitui FALSA contraindicação à vacinação:', '["resfriado leve, sem febre alta.","reação anafilática a dose anterior da mesma vacina.","imunodeficiência grave para vacinas vivas.","gestação para a vacina tríplice viral.","alergia grave confirmada a componente da vacina."]'::jsonb, 0, 'Doenças leves, uso de antibiótico e desnutrição não impedem a vacinação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
insert into public.questoes (id, area, texto_id, enunciado, alternativas, correta, comentario) values ('tec-134', 'tec', null, 'Sobre a evolução da lesão vacinal da BCG, é correto afirmar:', '["evolui de mácula a pápula, pústula, úlcera e crosta, deixando cicatriz em cerca de 6 a 12 semanas, sem necessidade de curativo.","deve ser coberta com curativo oclusivo e pomada antibiótica.","a formação de úlcera indica erro de técnica e exige revacinação.","a ausência de cicatriz exige revacinação imediata em todos os casos.","deve ser espremida para drenar a secreção."]'::jsonb, 0, 'A lesão deve ser mantida limpa, sem curativos ou medicamentos. A ausência de cicatriz não indica revacinação.') on conflict (id) do update set area = excluded.area, texto_id = excluded.texto_id, enunciado = excluded.enunciado, alternativas = excluded.alternativas, correta = excluded.correta, comentario = excluded.comentario;
